def choose_move(observation):
    wx, hy = observation['grid_width'], observation['grid_height']
    dx, dy = 0, 0
    mx, my = observation['self_position']
    ox, oy = observation.get('opponent_position', (mx, my))
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    # Choose nearest resource
    target = None
    min_dist = float('inf')
    for res in resources:
        rx, ry = res['x'], res['y']
        if (rx, ry) not in obstacles:
            d = dist((mx, my), (rx, ry))
            if d < min_dist:
                min_dist, target = d, (rx, ry)
    # Decide move
    if target:
        dx = 1 if target[0] > mx else -1 if target[0] < mx else 0
        dy = 1 if target[1] > my else -1 if target[1] < my else 0
        # Prioritize horizontal move if distance is greater
        if abs(target[0] - mx) >= abs(target[1] - my):
            if (mx + dx, my) not in obstacles and 0 <= mx + dx < wx:
                return [dx, 0]
            elif (mx, my + dy) not in obstacles and 0 <= my + dy < hy:
                return [0, dy]
        else:
            if (mx, my + dy) not in obstacles and 0 <= my + dy < hy:
                return [0, dy]
            elif (mx + dx, my) not in obstacles and 0 <= mx + dx < wx:
                return [dx, 0]
    # No resources or blocked path, move towards opponent
    odx = 1 if ox > mx else -1 if ox < mx else 0
    ody = 1 if oy > my else -1 if oy < my else 0
    # Try horizontal
    if (mx + odx, my) not in obstacles and 0 <= mx + odx < wx:
        return [odx, 0]
    # Try vertical
    if (mx, my + ody) not in obstacles and 0 <= my + ody < hy:
        return [0, ody]
    # Else stay still
    return [0, 0]
